## 4️⃣ Integration & Deployment

| Step | Tool | Why |
|------|------|-----|
| **Payment** | Stripe / PayPal SDK | Handles PCI‑DSS, tokenization, webhooks |
| **Auth** | Auth0 / Firebase Auth | Secure login, social providers |
| **SSR / SSG** | Next.js `getStaticProps` / `getServerSideProps` | SEO, faster first paint |
| **Analytics** | Google Analytics / Plausible | Track conversions |
| **CI/CD** | GitHub Actions / Vercel | Automated linting, tests, deploy |
| **Hosting** | Vercel / Netlify | Edge caching, instant rollbacks |
| **CDN** | Cloudflare / Fastly | Global image delivery, caching |
| **Monitoring** | Sentry / LogRocket | Runtime errors, user session replay |

### Example: Stripe Checkout Flow

```tsx
// src/pages/checkout.tsx
import { useCart } from '../../context/CartContext';
import { useRouter } from 'next/router';
import { useEffect } from 'react';

export default function Checkout() {
  const { state } = useCart();
  const router = useRouter();

  useEffect(() => {
    const createCheckoutSession = async () => {
      const res = await fetch('/api/create-checkout-session', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ items: state.items }),
      });
      const { url } = await res.json();
      window.location.href = url;
    };
    createCheckoutSession();
  }, []);

  return <p>Redirecting to payment...</p>;
}
```

**API Route (`pages/api/create-checkout-session.ts`)**

```ts
import { NextApiRequest, NextApiResponse } from 'next';
import Stripe from 'stripe';

const stripe = new Stripe(process.env.STRIPE_SECRET_KEY!, {
  apiVersion: '2023-10-16',
});

export default async function handler(req: NextApiRequest, res: NextApiResponse) {
  if (req.method !== 'POST') return res.status(405).end();

  const { items } = req.body;
  const line_items = items.map((item: any) => ({
    price_data: {
      currency: 'usd',
      product_data: { name: item.name },
      unit_amount: Math.round(item.price * 100),
    },
    quantity: item.quantity,
  }));

  const session = await stripe.checkout.sessions.create({
    payment_method_types: ['card'],
    line_items,
    mode: 'payment',
    success_url: `${process.env.NEXT_PUBLIC_SITE_URL}/success`,
    cancel_url: `${process.env.NEXT_PUBLIC_SITE_URL}/cancel`,
  });

  res.json({ url: session.url });
}
```

